# -*- coding: utf-8 -*-
"""
WMS（海外仓）操作：一件代发 > 平台订单
流程：筛选未发货 -> 全选 -> 批量修改快递方(按店铺优先级，从上往下) -> 批量发货
      每个快递方发一轮，失败的留在"未发货"，下一个快递方再发（实现"依次往下试"）。
DRY_RUN=True 时不真正点击"确认/批量发货"，只记录将要执行的动作。
"""
import time
import config, core
from core import log, ORDERINFO_WMS
from rules import courier_priority, ALL_COURIERS


def open_platform_orders(page):
    core.safe_goto(page, ORDERINFO_WMS)
    time.sleep(4)


def count_rows(page):
    """未发货订单数。优先读分页 '共 N 条'（el-table 固定列会使 .el-table__row 翻倍，不能直接数行）。"""
    import re
    el = page.query_selector(".el-pagination__total")
    if el:
        m = re.findall(r"\d+", el.inner_text() or "")
        if m:
            return int(m[0])
    rows = page.query_selector_all(".el-table__row")
    return len(rows) // 2 if rows else 0


def close_tips(page, rounds=4):
    """关闭所有可见 el-message-box / Tip（点 ok/确定/关闭），返回文本列表。"""
    texts = []
    for _ in range(rounds):
        box = page.query_selector(".el-message-box__wrapper:visible .el-message-box")
        if not box:
            break
        try:
            texts.append((box.inner_text() or "").strip()[:120])
        except Exception:
            pass
        done = False
        for t in ["ok", "OK", "确定", "确认", "关闭", "知道了"]:
            b = page.query_selector(f".el-message-box__wrapper:visible button:has-text('{t}')")
            if b and b.is_visible():
                try: b.click(); done = True
                except Exception: pass
                break
        if not done:
            try: page.keyboard.press("Escape")
            except Exception: pass
        time.sleep(1)
    return texts


def ensure_unshipped_filter(page):
    """确保状态筛选为'未发货'并查询。页面默认即为未发货，这里点一次查询刷新。"""
    try:
        page.click("button:has-text('查询')", timeout=5000)
        time.sleep(3)
    except Exception as e:
        log(f"[WMS] 点击查询失败: {e}")


def select_all(page):
    """勾选表头全选框。无数据时该框禁用，返回 False。"""
    header_cb = page.query_selector(".el-table__header-wrapper .el-checkbox, .el-table__header .el-checkbox")
    if not header_cb:
        return False
    cls = header_cb.get_attribute("class") or ""
    if "is-disabled" in cls:
        return False
    try:
        header_cb.click()
        time.sleep(1)
        return True
    except Exception as e:
        log(f"[WMS] 全选失败: {e}")
        return False


def set_courier(page, courier):
    """打开'批量修改快递方'弹窗，选择 courier，确认。DRY_RUN 下不点确认。"""
    try:
        page.click("button:has-text('批量修改快递方')", timeout=6000)
    except Exception as e:
        log(f"[WMS] 打开'批量修改快递方'失败: {e}")
        return False
    time.sleep(1.5)
    # 可见弹窗(:visible)内的 快递方 下拉（页面存在多个隐藏 el-dialog，必须限定可见）
    try:
        page.click(".el-dialog:visible .el-select", timeout=4000)
        time.sleep(1)
        opt = None
        for el in page.query_selector_all(".el-select-dropdown__item"):
            if el.is_visible() and (el.inner_text() or "").strip() == courier:
                opt = el; break
        if not opt:
            log(f"[WMS] 未找到快递方选项 {courier}")
            _close_dialog(page)
            return False
        opt.click()
        time.sleep(0.5)
    except Exception as e:
        log(f"[WMS] 选择快递方 {courier} 失败: {e}")
        _close_dialog(page)
        return False

    if config.DRY_RUN:
        log(f"[WMS][DRY] 将设置快递方 = {courier}（跳过'确认'）")
        _close_dialog(page)
        return True
    try:
        # 确认按钮：可见弹窗内的 primary 按钮（文本'确认'，与'取消'区分）
        ok = page.query_selector(".el-dialog:visible button.el-button--primary")
        if not ok:
            for b in page.query_selector_all(".el-dialog:visible button"):
                if (b.inner_text() or "").replace(" ", "") in ("确认", "确定"):
                    ok = b; break
        if not ok:
            log("[WMS] 未找到可见确认按钮"); return False
        ok.click()
        time.sleep(2)
        tips = close_tips(page)   # 关掉"成功"Tip，否则挡住后续批量发货
        log(f"[WMS] 已设置快递方 = {courier}  Tip={tips}")
        return True
    except Exception as e:
        log(f"[WMS] 确认快递方失败: {e}")
        return False


def _close_dialog(page):
    try:
        page.click(".el-dialog button:has-text('取消')", timeout=2000)
    except Exception:
        try:
            page.keyboard.press("Escape")
        except Exception:
            pass
    time.sleep(0.5)


def batch_ship(page):
    """点击'批量发货'，处理'预发货成功'提示。DRY_RUN 下不执行。"""
    if config.DRY_RUN:
        log("[WMS][DRY] 将点击'批量发货'（已跳过）")
        return True
    try:
        page.click("button:has-text('批量发货')", timeout=6000)
        time.sleep(2)
        # 可能的二次确认（限可见弹窗）
        for t in ["确定", "确认", "ok", "OK"]:
            b = page.query_selector(f".el-message-box__wrapper:visible button:has-text('{t}'), .el-dialog:visible button:has-text('{t}')")
            if b and b.is_visible():
                try: b.click(); time.sleep(1.5)
                except Exception: pass
                break
        time.sleep(2)
        tips = close_tips(page)   # 捕获并关闭 'Tip: 预发货成功'
        ok = any("预发货成功" in t or "成功" in t for t in tips)
        log(f"[WMS] 已执行批量发货  结果Tip={tips}")
        return ok if tips else True
    except Exception as e:
        log(f"[WMS] 批量发货失败: {e}")
        return False


def read_order_numbers(page):
    """读当前未发货列表的平台订单号（去重）。订单号形如 P2AC6TCD61443。"""
    try:
        nums = page.evaluate(r"""() => {
            const s=new Set();
            document.querySelectorAll('.el-table__row').forEach(r=>{
                const m=(r.innerText||'').match(/P[0-9A-Z]{9,15}/g); if(m) m.forEach(x=>s.add(x));
            });
            return [...s];
        }""")
        return nums or []
    except Exception:
        return []


def process_shop(page, account, already_logged_in=False):
    """处理单个店铺：按快递方优先级逐轮发货。返回 {shop, before, left, left_orders}。"""
    priority = courier_priority(account["login"])
    log(f"[WMS] === 处理店铺 {account['shop']}（{account['login']}），快递方优先级 {priority} ===")
    if not already_logged_in and not core.wms_login(page, account):
        log(f"[WMS] {account['shop']} 登录失败，跳过")
        return {"shop": account["shop"], "error": "登录失败", "left_orders": []}
    open_platform_orders(page)
    ensure_unshipped_filter(page)

    total_before = count_rows(page)
    log(f"[WMS] {account['shop']} 未发货订单 ≈ {total_before} 条")
    if total_before == 0:
        log(f"[WMS] {account['shop']} 无未发货订单")
        return {"shop": account["shop"], "before": 0, "left": 0, "left_orders": []}

    limit = config.MAX_ORDERS_PER_RUN
    for courier in priority:
        open_platform_orders(page)
        ensure_unshipped_filter(page)
        remaining = count_rows(page)
        if remaining == 0:
            log(f"[WMS] {account['shop']} 已全部发出")
            break
        if limit and remaining > limit:
            log(f"[WMS][安全] 未发货 {remaining} > 单次上限 {limit}，建议调大 MAX_ORDERS_PER_RUN 或分批。")
        log(f"[WMS] 用快递方 [{courier}] 处理剩余 {remaining} 条")
        if not select_all(page):
            log("[WMS] 无法全选（可能无数据/禁用）"); break
        if not set_courier(page, courier):
            continue
        # 改快递方后列表会刷新、丢失勾选，发货前重新全选
        if not select_all(page):
            log("[WMS] 改快递方后重新全选失败，跳过本轮发货"); continue
        batch_ship(page)
        time.sleep(2)

    open_platform_orders(page)
    ensure_unshipped_filter(page)
    left = count_rows(page)
    left_orders = read_order_numbers(page) if left else []
    dry = "（DRY_RUN 未真正发货）" if config.DRY_RUN else ""
    log(f"[WMS] {account['shop']} 处理完成，仍未发货 ≈ {left} 条{dry}")
    if left and not config.DRY_RUN:
        log(f"[WMS] ⚠️ {account['shop']} 试完所有快递方仍未发货：{left_orders}")
    return {"shop": account["shop"], "before": total_before, "left": left, "left_orders": left_orders}

# -*- coding: utf-8 -*-
"""
ERP（赛狐 Sellfox）操作：订单 > 订单处理（订单发货）
=== 第一步：物流下单（对应视频前 50 多秒）===
  在【待处理】视图，(可选)按渠道筛选 -> 全选订单 -> 点击【物流下单】把订单投入海外仓
  -> 读取结果弹窗「成功X 失败Y」(失败常见：所选仓库库存不足)。
DRY_RUN=True 时：完成 切视图/筛选/全选/统计，但【不】点击"物流下单"，只记录将处理的订单数。

其它阶段(审核通过/确认发货/获取跟踪单号)见后续，同样受 DRY_RUN 保护。
"""
import re, time
import config, core
from core import log


# ---------------- 打开与导航 ----------------
def open_order_ship(page):
    core.safe_goto(page, config.ERP_URL)
    for _ in range(30):
        time.sleep(1)
        if page.query_selector(".el-table") or page.query_selector("text=订单处理"):
            break
    time.sleep(2)
    dismiss_alert_modal(page)


def dismiss_alert_modal(page):
    """关闭落地时弹出的「订单异常提醒」等拦截弹窗（点 稍后处理/关闭），避免挡住后续操作。"""
    for _ in range(3):
        closed = False
        for t in ["稍后处理", "关 闭", "关闭", "我知道了", "取 消", "取消"]:
            b = page.query_selector(f".el-dialog:visible button:has-text('{t}'), .el-message-box:visible button:has-text('{t}')")
            if b and b.is_visible():
                try:
                    b.click(); closed = True; time.sleep(1)
                except Exception:
                    pass
                break
        if not closed:
            break


def goto_view(page, name):
    """点击左侧导航切换视图，如 '待处理' / '待审核'。"""
    try:
        page.click(f"text={name}", timeout=6000)
        time.sleep(3)
        log(f"[ERP] 切换到视图：{name}")
        return True
    except Exception as e:
        log(f"[ERP] 切换视图 {name} 失败: {e}")
        return False


def report_counts(page):
    labels = ["待审核", "待处理", "自营仓库", "三方仓", "有货", "缺货", "已发货", "已搁置", "异常处理"]
    result = {}
    for lb in labels:
        try:
            el = page.query_selector(f"text={lb}")
            num = None
            if el:
                parent = el.evaluate_handle("e=>e.parentElement")
                txt = page.evaluate("e=>e.innerText", parent)
                m = re.findall(r"\d+", txt or "")
                num = m[-1] if m else None
            result[lb] = num
        except Exception:
            result[lb] = None
    log(f"[ERP] 阶段统计: {result}")
    return result


# ---------------- 渠道筛选（可选） ----------------
def filter_by_channel(page, channel_keyword):
    """在「全部渠道」多选弹层里选中 == channel_keyword 的渠道并确定。channel_keyword=None 不筛选。
    实测：触发控件 input[placeholder*='渠道']；渠道选项是 span.main_label（精确匹配文本，
    别用包含匹配——订单行 物流信息列 也含渠道文字会误点）；弹层有 取消/确定。"""
    if not channel_keyword:
        return True
    try:
        page.click("input[placeholder*='渠道']", timeout=5000)
        time.sleep(1.2)
        picked = False
        for el in page.query_selector_all("span.main_label"):
            try:
                if el.is_visible() and (el.inner_text() or "").strip() == channel_keyword:
                    el.click(); picked = True
                    log(f"[ERP] 渠道选中: {channel_keyword}")
                    break
            except Exception:
                continue
        if not picked:
            log(f"[ERP] 未找到渠道选项: {channel_keyword}")
            try: page.keyboard.press("Escape")
            except Exception: pass
            return False
        time.sleep(0.5)
        # 确定（限可见弹层）
        for t in ["确定", "确认"]:
            b = page.query_selector(f".el-popper:visible button:has-text('{t}')")
            if not (b and b.is_visible()):
                b = page.query_selector(f"button:has-text('{t}'):visible")
            if b and b.is_visible():
                b.click(); break
        time.sleep(2.5)
        return True
    except Exception as e:
        log(f"[ERP] 渠道筛选失败: {e}")
        return False


# ---------------- 选择与下单 ----------------
def _find_toolbar_button(page, text):
    """定位工具栏批量按钮：文本恰为 text、不在 vxe 表格行内、可见、y 最靠上的那个。
    返回 elementhandle（用于 Playwright 真实点击）。"""
    target, ty = None, None
    for h in page.query_selector_all("button, .el-button, .base_button_comp, .myj-btn, [class*=btn]"):
        try:
            if (h.inner_text() or "").replace("　", " ").replace(" ", "").strip() != text:
                continue
            if h.evaluate("e=>!!e.closest('.vxe-body--row')"):
                continue
            if not h.is_visible():
                continue
            bb = h.bounding_box()
            if not bb:
                continue
            if target is None or bb["y"] < ty:
                target, ty = h, bb["y"]
        except Exception:
            continue
    return target



def count_orders(page):
    """读取订单总数。订单表是 vxe-table，自定义分页把总数拆成
    `共 <span class=total_style>N</span> 条`，故读 .total_style（页面可能有多个分页实例，取最大值）。
    数据是异步加载的：轮询等待 total>0 或超时。"""
    for _ in range(20):
        try:
            n = page.evaluate(
                "() => { const a=[...document.querySelectorAll('.total_style')]"
                ".map(e=>parseInt((e.innerText||'0').replace(/\\D/g,''),10))"
                ".filter(x=>!isNaN(x)); return a.length? Math.max(...a):0; }"
            )
            if n and n > 0:
                return int(n)
        except Exception:
            pass
        time.sleep(1)
    # 兜底：按去重后的 vxe 行数（固定列会翻倍，用逻辑行组 .parentRowGroup）
    try:
        return page.evaluate("() => document.querySelectorAll('.parentRowGroup').length")
    except Exception:
        return 0


def select_all(page):
    """点击 vxe-table 表头全选框，并校验确有行被勾选。"""
    th = page.query_selector(".vxe-header--column.col--checkbox .vxe-cell--checkbox")
    if not th:
        log("[ERP] 未找到 vxe 表头全选框"); return False
    if "is--disabled" in (th.get_attribute("class") or ""):
        log("[ERP] 表头全选框禁用（可能无数据）"); return False
    try:
        th.click(); time.sleep(1.5)
    except Exception as e:
        log(f"[ERP] 全选点击失败: {e}"); return False
    checked = page.evaluate(
        "() => document.querySelectorAll('.vxe-body--row.row--checked, .vxe-cell--checkbox.is--checked').length"
    )
    if not checked:
        log("[ERP] 全选后未检测到勾选行"); return False
    log(f"[ERP] 已全选，勾选标记数≈{checked}")
    return True


def parse_result_text(txt):
    """从结果框文本解析 成功/失败数 与失败订单号。返回 {success,fail,fail_orders,text}。"""
    if not txt:
        return {"success": None, "fail": None, "fail_orders": [], "text": ""}
    ms = re.search(r"成功[:：]?\s*(\d+)", txt)
    mf = re.search(r"失败[:：]?\s*(\d+)", txt)
    # 订单/包裹号形如 P2AC6TCD61425（P + 十余位字母数字）
    orders = re.findall(r"\bP[0-9A-Z]{9,15}\b", txt)
    # 去掉可能混入的表头等，保留失败区（有失败时才收集）
    return {
        "success": int(ms.group(1)) if ms else None,
        "fail": int(mf.group(1)) if mf else None,
        "fail_orders": list(dict.fromkeys(orders)),
        "text": txt,
    }


def read_result_dialog(page):
    """读取物流下单后的结果弹窗文本（成功X 失败Y + 原因），解析后关闭。返回 parse 字典。"""
    txt = None
    for _ in range(30):
        dlg = page.query_selector(".el-dialog__wrapper:not([style*='display: none']) .el-dialog, .el-message-box")
        if dlg:
            try: txt = (dlg.inner_text() or "").strip()
            except Exception: pass
            break
        time.sleep(1)
    if txt:
        log("[ERP] 物流下单结果:\n" + txt[:800])
    # 关闭
    for t in ["关闭", "关 闭", "确定", "确 定", "ok"]:
        b = page.query_selector(f".el-dialog button:has-text('{t}'), .el-message-box__btns button:has-text('{t}')")
        if b:
            try: b.click(); break
            except Exception: pass
    time.sleep(1)
    return parse_result_text(txt)


def place_logistics_orders(page, channel_keyword=None):
    """
    第一步核心：待处理视图 -> (可选渠道筛选) -> 全选 -> 物流下单 -> 读结果。
    DRY_RUN 下不点击"物流下单"。
    """
    open_order_ship(page)
    if not goto_view(page, "待处理"):
        return
    filter_by_channel(page, channel_keyword)
    n = count_orders(page)
    log(f"[ERP] 待处理订单 共 {n} 条" + (f"（渠道过滤: {channel_keyword}）" if channel_keyword else ""))
    if n == 0:
        log("[ERP] 无待处理订单"); return {"count": 0, "success": 0, "fail": 0, "fail_orders": []}

    if not select_all(page):
        log("[ERP] 全选失败，终止物流下单"); return {"count": n, "error": "全选失败"}

    if config.DRY_RUN:
        log(f"[ERP][DRY] 将点击【物流下单】处理 {n} 条订单（已跳过实际点击）")
        return {"count": n, "dry_run": True}

    # 点"物流下单"。行内也有同名按钮，必须点工具栏批量按钮。
    # 关键：必须用 Playwright 真实点击(elementhandle.click)，JS 合成 click 不触发 Vue 事件！
    btn = _find_toolbar_button(page, "物流下单")
    if not btn:
        log("[ERP] 未定位到工具栏【物流下单】按钮"); return {"count": n, "error": "未找到物流下单按钮"}
    try:
        btn.click()
        log(f"[ERP] 已点击工具栏【物流下单】，处理 {n} 条")
    except Exception as e:
        log(f"[ERP] 点击物流下单失败: {e}"); return {"count": n, "error": str(e)}
    time.sleep(3)
    r = read_result_dialog(page)
    if r.get("fail"):
        log(f"[ERP] ⚠️ 物流下单失败 {r['fail']} 单：{r['fail_orders']}")
    return {"count": n, "success": r.get("success"), "fail": r.get("fail"),
            "fail_orders": r.get("fail_orders", []), "result_text": r.get("text")}


# ---------------- 订单状态更新（三方仓>待更新>手动更新，获取跟踪号）----------------
def _toolbar_btn_coord(page, text):
    """返回工具栏(非行内)中 去空白后文本==text 的按钮中心坐标 {x,y}（取最内层）。无则 None。"""
    return page.evaluate(r"""(text) => {
        const norm = s => (s||'').replace(/\s+/g,'');
        let best=null;
        document.querySelectorAll('button, .el-button, .base_button_comp, [class*=btn]').forEach(e=>{
            if(e.offsetParent===null) return;
            if(norm(e.innerText)!==text) return;
            if(e.closest('.vxe-body--row')) return;   // 排除行内同名按钮
            const r=e.getBoundingClientRect();
            const desc=e.querySelectorAll('*').length;
            if(!best || desc<best.desc) best={desc, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)};
        });
        return best;
    }""", text)


def update_order_status(page):
    """订单状态更新：三方仓 -> 待更新 子标签 -> 工具栏【手动更新】-> 拉取跟踪号 ->
    读「获取完成 共N包裹 已获取X 失败Y」-> 关闭。不分渠道。返回 {total,got,fail,text}。
    此操作只拉取/更新状态，不发货，DRY_RUN 也执行（属只读性质的状态同步）。"""
